/* ---------- Assemble: V1 raw + metadata, then V2 quests ---------- */
const mapLegacy = (r, i) => {
  const [type, mood, environment, socialLevel, weirdness, confidence, mission, complete, variation, say] = legacy[i];
  return {
    id: `${i + 1}`,
    title: r[0], category: r[1], minutes: r[2], difficulty: r[3],
    description: r[4], skill: r[5], why: r[6], need: r[7], steps: r[8],
    interests: r[9], icon: r[10],
    type, mood, environment, socialLevel, weirdness, confidence,
    questChain: null, mystery: null,
    detail: { what: r[4], mission, say: say || [], complete, variation }
  };
};

const mapExtra = (e, i) => ({
  id: `${raw.length + i + 1}`,
  title: e.t, category: e.c, minutes: e.m, difficulty: e.df,
  description: e.desc, skill: e.sk, why: e.why, need: e.need, steps: e.steps,
  interests: e.int, icon: e.ic,
  type: e.ty, mood: e.mood, environment: e.env,
  socialLevel: e.soc, weirdness: e.wd, confidence: e.cf,
  questChain: e.chain || null, mystery: e.mystery || null,
  detail: {
    what: e.what, mission: e.mission, say: e.say || [], where: e.where,
    notes: e.notes || [], complete: e.done, variation: e.alt
  }
});

/* "Vibes" power the I'm Bored picker. A quest can match several. */
const deriveVibes = (q) => {
  const v = [];
  if (q.category === 'Creative' || q.type === 'Creative') v.push('make');
  if (q.category === 'Skill-building' || q.type === 'Tech' || /^(Learn|Memori[sz]e|Identify|Decode|Find out)/i.test(q.title)) v.push('learn');
  if (q.type === 'Physical' ||
      (['outside', 'around-town'].includes(q.environment) && q.socialLevel === 0)) v.push('move');
  if (q.socialLevel >= 1) v.push('socialize');
  if (q.type === 'Chill' || q.mood === 'calm') v.push('chill');
  if (q.weirdness >= 2 || ['Weird', 'Mildly Unhinged'].includes(q.type)) v.push('weird');
  return v;
};

/* Fill every detail section so the quest page always has useful content. */
const finish = (q) => {
  q.retired = RETIRED_IDS.has(q.id);
  if (!CATEGORY_INFO[q.category]) q.category = 'Weird-but-safe';
  q.icon = (typeof q.icon === 'string' && q.icon.trim()) || CATEGORY_INFO[q.category]?.fallback || DEFAULT_ICON;
  q.vibes = deriveVibes(q);
  const env = ENVIRONMENTS[q.environment];
  const d = q.detail;
  q.nearby = env.nearby;
  q.detail = {
    what: d.what || q.description,
    mission: d.mission || q.description,
    say: d.say || [],
    where: d.where || env.where,
    notes: [
      ...(d.notes || []),
      ...(BOUNDARIES[q.socialLevel] || []),
      ...(env.nearby ? [OUTSIDE_SAFETY] : [])
    ],
    complete: d.complete || 'You’ve followed the steps and finished the quest.',
    variation: d.variation || null
  };
  return q;
};

/* Every quest ever shipped, in id order. Use for anything that looks up history. */
const allQuests = [
  ...raw.map(mapLegacy),
  ...extra.map(mapExtra)
].map(finish);

/* The curated library: what people can discover, roll, and get as a daily. */
const quests = allQuests.filter((q) => !q.retired);

if (legacy.length !== raw.length) {
  console.warn('SideQuest: legacy metadata length does not match raw quests.');
}

const categories = Object.keys(CATEGORY_INFO);
const categoryInfo = (id) => CATEGORY_INFO[id] || CATEGORY_INFO['Weird-but-safe'];
/* History-safe lookup: finds retired quests too. Unknown ids fall back to the first quest. */
const questById = (id) => allQuests.find(q => q.id === id) ?? allQuests[0];
const matchingQuests = (interests) => quests.filter(q => q.interests.some(i => interests.includes(i)));
const TYPE_COLORS = {
  'Confidence': '#f7745f', 'Chill': '#7ec8e3', 'Social Chaos': '#c9b3ea',
  'Mildly Unhinged': '#ffd84d', 'Weird': '#b9e86c', 'Real World': '#8fd6a4',
  'Creative': '#ff9fc2', 'Physical': '#ffb36b', 'Tech': '#9db4ff', 'Random': '#d7f05a'
};
const typeColor = (id) => TYPE_COLORS[id] || '#d7f05a';

const typeInfo = (id) => QUEST_TYPES.find(t => t.id === id) || QUEST_TYPES[QUEST_TYPES.length - 1];
const timeBucket = (q) => TIME_BUCKETS.find(b => q.minutes >= b.min && q.minutes <= b.max)?.id || '60';

export {
  quests, allQuests, categories, categoryInfo, CATEGORY_INFO, RETIRED_IDS, questById, matchingQuests,
  QUEST_TYPES, ENVIRONMENTS, TIME_BUCKETS, typeInfo, timeBucket, typeColor
};
